PigeonInternalCodecSerializer::PigeonInternalCodecSerializer() {}

EncodableValue PigeonInternalCodecSerializer::ReadValueOfType(
  uint8_t type,
  ::flutter::ByteStreamReader* stream) const {
  switch (type) {
    case 129: {
        return CustomEncodableValue(PlatformAppInfo::FromEncodableList(std::get<EncodableList>(ReadValue(stream))));
      }
    case 130: {
        return CustomEncodableValue(PlatformOsInfo::FromEncodableList(std::get<EncodableList>(ReadValue(stream))));
      }
    case 131: {
        return CustomEncodableValue(PlatformDeviceInfo::FromEncodableList(std::get<EncodableList>(ReadValue(stream))));
      }
    case 132: {
        return CustomEncodableValue(PlatformCpuInfo::FromEncodableList(std::get<EncodableList>(ReadValue(stream))));
      }
    case 133: {
        return CustomEncodableValue(PlatformMemoryInfo::FromEncodableList(std::get<EncodableList>(ReadValue(stream))));
      }
    case 134: {
        return CustomEncodableValue(PlatformStorageInfo::FromEncodableList(std::get<EncodableList>(ReadValue(stream))));
      }
    case 135: {
        return CustomEncodableValue(PlatformGpuInfo::FromEncodableList(std::get<EncodableList>(ReadValue(stream))));
      }
    case 136: {
        return CustomEncodableValue(PlatformBatteryInfo::FromEncodableList(std::get<EncodableList>(ReadValue(stream))));
      }
    case 137: {
        return CustomEncodableValue(PlatformNetworkInfo::FromEncodableList(std::get<EncodableList>(ReadValue(stream))));
      }
    default:
      return ::flutter::StandardCodecSerializer::ReadValueOfType(type, stream);
    }
}

void PigeonInternalCodecSerializer::WriteValue(
  const EncodableValue& value,
  ::flutter::ByteStreamWriter* stream) const {
  if (const CustomEncodableValue* custom_value = std::get_if<CustomEncodableValue>(&value)) {
    if (custom_value->type() == typeid(PlatformAppInfo)) {
      stream->WriteByte(129);
      WriteValue(EncodableValue(std::any_cast<PlatformAppInfo>(*custom_value).ToEncodableList()), stream);
      return;
    }
    if (custom_value->type() == typeid(PlatformOsInfo)) {
      stream->WriteByte(130);
      WriteValue(EncodableValue(std::any_cast<PlatformOsInfo>(*custom_value).ToEncodableList()), stream);
      return;
    }
    if (custom_value->type() == typeid(PlatformDeviceInfo)) {
      stream->WriteByte(131);
      WriteValue(EncodableValue(std::any_cast<PlatformDeviceInfo>(*custom_value).ToEncodableList()), stream);
      return;
    }
    if (custom_value->type() == typeid(PlatformCpuInfo)) {
      stream->WriteByte(132);
      WriteValue(EncodableValue(std::any_cast<PlatformCpuInfo>(*custom_value).ToEncodableList()), stream);
      return;
    }
    if (custom_value->type() == typeid(PlatformMemoryInfo)) {
      stream->WriteByte(133);
      WriteValue(EncodableValue(std::any_cast<PlatformMemoryInfo>(*custom_value).ToEncodableList()), stream);
      return;
    }
    if (custom_value->type() == typeid(PlatformStorageInfo)) {
      stream->WriteByte(134);
      WriteValue(EncodableValue(std::any_cast<PlatformStorageInfo>(*custom_value).ToEncodableList()), stream);
      return;
    }
    if (custom_value->type() == typeid(PlatformGpuInfo)) {
      stream->WriteByte(135);
      WriteValue(EncodableValue(std::any_cast<PlatformGpuInfo>(*custom_value).ToEncodableList()), stream);
      return;
    }
    if (custom_value->type() == typeid(PlatformBatteryInfo)) {
      stream->WriteByte(136);
      WriteValue(EncodableValue(std::any_cast<PlatformBatteryInfo>(*custom_value).ToEncodableList()), stream);
      return;
    }
    if (custom_value->type() == typeid(PlatformNetworkInfo)) {
      stream->WriteByte(137);
      WriteValue(EncodableValue(std::any_cast<PlatformNetworkInfo>(*custom_value).ToEncodableList()), stream);
      return;
    }
  }
  ::flutter::StandardCodecSerializer::WriteValue(value, stream);
}

